    <!-- Scoped property-card slider and view controls -->
    <style id="dre-property-card-controls-css">
      .oc-img { position: relative; overflow: hidden; }
      .oc-img .oc-slides { display: flex !important; flex-wrap: nowrap !important; width: 100%; height: 100%; transition: transform .35s ease; will-change: transform; }
      .oc-img .oc-slides > img { display: block !important; flex: 0 0 100% !important; width: 100% !important; min-width: 100% !important; max-width: 100% !important; height: 100%; object-fit: cover; }
      .oc-img .oc-nav { position: absolute; z-index: 20; cursor: pointer; pointer-events: auto; }
      .oc-img .oc-dots { position: absolute; z-index: 20; pointer-events: auto; }
      .oc-img .oc-dots i { display: inline-block; cursor: pointer; pointer-events: auto; }
      #opGrid.is-list { display: flex !important; flex-direction: column !important; }
      #opGrid.is-list > .oc { display: grid !important; grid-template-columns: minmax(220px, 36%) minmax(0, 1fr) !important; }
      #opGrid.is-list > .oc > .oc-img { height: auto; min-height: 230px; }
      @media (max-width: 640px) { #opGrid.is-list > .oc { grid-template-columns: minmax(0, 1fr) !important; } #opGrid.is-list > .oc > .oc-img { min-height: 220px; } }
    </style>
    <script>
    (function () {
      function initDrePropertyControls() {
        // Initialise every property-card slider on these pages, including featured cards outside #opGrid.
        document.querySelectorAll('.oc-img').forEach(function (frame) {
          var track = frame.querySelector('.oc-slides');
          if (!track || track.dataset.dreSliderReady === '1') return;
          var imgs = Array.prototype.slice.call(track.querySelectorAll('img'));
          if (!imgs.length) return;
          track.dataset.dreSliderReady = '1';
          track.style.display = 'flex';
          track.style.flexWrap = 'nowrap';
          track.style.width = '100%';
          track.style.height = '100%';
          imgs.forEach(function (img) {
            img.style.flex = '0 0 100%';
            img.style.width = '100%';
            img.style.minWidth = '100%';
            img.style.maxWidth = '100%';
          });
          var dotsWrap = frame.querySelector('.oc-dots');
          var dots = dotsWrap ? Array.prototype.slice.call(dotsWrap.querySelectorAll('i')) : [];
          var prev = frame.querySelector('.oc-nav.p');
          var next = frame.querySelector('.oc-nav.n');
          var index = 0;
          function show(n) {
            index = (n + imgs.length) % imgs.length;
            track.style.transform = 'translate3d(' + (-index * 100) + '%,0,0)';
            dots.forEach(function (dot, i) { dot.classList.toggle('on', i === index); });
            if (prev) prev.style.display = imgs.length > 1 ? '' : 'none';
            if (next) next.style.display = imgs.length > 1 ? '' : 'none';
            if (dotsWrap) dotsWrap.style.display = imgs.length > 1 ? '' : 'none';
          }
          if (prev) prev.addEventListener('click', function (e) { e.preventDefault(); e.stopPropagation(); show(index - 1); });
          if (next) next.addEventListener('click', function (e) { e.preventDefault(); e.stopPropagation(); show(index + 1); });
          dots.forEach(function (dot, i) { dot.addEventListener('click', function (e) { e.preventDefault(); e.stopPropagation(); show(i); }); });
          show(0);
        });

        var grid = document.getElementById('opGrid');
        if (!grid) return;
        document.querySelectorAll('.vt [data-v]').forEach(function (button) {
          if (button.dataset.dreViewReady === '1') return;
          button.dataset.dreViewReady = '1';
          button.addEventListener('click', function (e) {
            e.preventDefault();
            var list = button.getAttribute('data-v') === 'list';
            grid.classList.toggle('is-list', list);
            document.querySelectorAll('.vt [data-v]').forEach(function (b) {
              var active = b.getAttribute('data-v') === (list ? 'list' : 'grid');
              b.classList.toggle('on', active);
              b.setAttribute('aria-pressed', active ? 'true' : 'false');
            });
          });
        });
      }
      if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', initDrePropertyControls);
      else initDrePropertyControls();
      // In case listing cards are rendered after the initial page load, retry on load.
      window.addEventListener('load', initDrePropertyControls);
    })();
    </script>


    <!-- Dedicated Trending Picks carousel controls; isolated from other sliders. -->
    <style id="dre-trending-carousel-fix">
      #exTrack { display: grid !important; grid-auto-flow: column !important; overflow-x: auto !important; scroll-snap-type: x mandatory; scroll-behavior: smooth; -webkit-overflow-scrolling: touch; }
      #exTrack > .oc { min-width: 0; scroll-snap-align: start; }
    </style>
    <script>
    (function () {
      function initTrendingPicksCarousel() {
        var track = document.getElementById('exTrack');
        var prev = document.getElementById('exPrev');
        var next = document.getElementById('exNext');
        if (!track || !prev || !next || track.dataset.dreTrendingReady === '1') return;
        track.dataset.dreTrendingReady = '1';
        function step() {
          var card = track.querySelector('.oc');
          if (!card) return Math.max(track.clientWidth * 0.8, 280);
          var style = window.getComputedStyle(track);
          var gap = parseFloat(style.columnGap || style.gap) || 22;
          return card.getBoundingClientRect().width + gap;
        }
        prev.addEventListener('click', function (event) {
          event.preventDefault(); event.stopImmediatePropagation();
          track.scrollBy({ left: -step(), behavior: 'smooth' });
        }, true);
        next.addEventListener('click', function (event) {
          event.preventDefault(); event.stopImmediatePropagation();
          track.scrollBy({ left: step(), behavior: 'smooth' });
        }, true);
      }
      if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', initTrendingPicksCarousel);
      else initTrendingPicksCarousel();
    })();
    </script>

